/-- Armsupport: the displayed mathematical construction or bound. This statement assumes [the law parameter](hyp:law), [the L parameter](hyp:L). [This is the stated defined object](goal). -/
def ArmSupport (law : ObservedLaw) (L : ℝ) : Prop :=
  ∀ a : Bool, ∀ᵐ x ∂design, law.Q a x {y | y=0 ∨ y = -L ∨ y=L}=1

47810469913f039a.statement:
/-- Every positive-weight law belongs to the specified class. This statement assumes [the π parameter](hyp:π), [the C parameter](hyp:C). [This is the stated defined object](goal). -/
def PriorSupported (π : FinitePrior) (C : Set ObservedLaw) : Prop :=
  ∀ i, 0 < priorWeight π i → priorLaw π i ∈ C

f9b2f2c5888ab509.statement:
/-- Mix the full original iid record laws using all finite family weights. This statement assumes [the n parameter](hyp:n), [the π parameter](hyp:π). [This is the stated defined object](goal). -/
def priorMixture (n : ℕ) (π : FinitePrior) : Measure (Dataset n) :=
  ∑ i : Fin π.1, ENNReal.ofReal (priorWeight π i) • Measure.pi (fun _ : Fin n => (priorLaw π i).P)

898a5633c09e5548.statement:
def frameCoord (K : ℕ) (i : Fin (K+1)) (x : ℝ) : ℝ :=
  if (i:ℝ)/K ≤ x ∧ x ≤ ((i:ℝ)+1)/K then Real.cos (Real.pi*((K:ℝ)*x-i)/2)
  else if 0 < i.val ∧ ((i:ℝ)-1)/K ≤ x ∧ x ≤ (i:ℝ)/K then Real.sin (Real.pi*((K:ℝ)*x-((i:ℝ)-1))/2)
  else 0 -- @realizes Frame(explicit cosine/sine finite-overlap frame)

855541d6486d6bff.statement:
def conversePrior (ν : Bool) (n : ℕ) (v : Params) : FinitePrior :=
  if roughBranch n v then copulaPrior ν v (roughK n v) (roughM n v)
    ((roughK n v:ℝ)^(-v.α)/16) (1/16) (rarity n v) (magnitude n v)
  else tentPrior ν n v -- @realizes piNull(null branch at nu=0) @realizes piAlt(alternative branch at nu=1)

148e1a834112f5af.statement:
/-- Mix the complete iid records under the branchwise converse prior. This statement assumes [the ν parameter](hyp:ν), [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def converseMixture (ν : Bool) (n : ℕ) (v : Params) : Measure (Dataset n) :=
  priorMixture n (conversePrior ν n v) -- @realizes MixNull(null iid mixture) @realizes MixAlt(alternative iid mixture)

a10d4e3c5070c3dc.statement:
/-- Mix the complete iid records under the branchwise converse prior. This statement assumes [the ν parameter](hyp:ν), [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def converseMixture (ν : Bool) (n : ℕ) (v : Params) : Measure (Dataset n) :=
  priorMixture n (conversePrior ν n v) -- @realizes MixNull(null iid mixture) @realizes MixAlt(alternative iid mixture)

23626bde4f646ee1.statement:
/-- Use the separate bounded copula tuning or signed-binary paired-tent family. This statement assumes [the ν parameter](hyp:ν), [the n parameter](hyp:n), [the w parameter](hyp:w). [This is the stated defined object](goal). [Defining clause 1](step:1) is used. [Defining clause 2](step:2) is used. -/
def boundedConversePrior (ν : Bool) (n : ℕ) (w : Smooth3) : FinitePrior :=
  let v := Params.ofBounded w
  if roughBranch n v then copulaPrior ν v (roughK n v) (roughM n v)
    ((roughK n v:ℝ)^(-v.α)/16) (2*(roughK n v:ℝ)^(-v.β)/256) (1/2) 1
  else binaryTentPrior ν n w

6e8c2241f2d1f030.statement:
/-- Select the moment-normalized rough mark size or the paired-tent mark size. This statement assumes [the n parameter](hyp:n), [the v parameter](hyp:v). [This is the stated defined object](goal). -/
def magnitude (n : ℕ) (v : Params) : ℝ :=
  if roughBranch n v then rarity n v^(-1/v.p) else tentMagnitude n v -- @realizes magnitude(branchwise derived mark size)

2be65fefb7e718c6.statement:
/-- The untruncated inverse-propensity score targets the original conditional mean effect. This statement assumes [the f parameter](hyp:f), [the o parameter](hyp:o). [This is the stated defined object](goal). -/
def ipwUntruncated (f : Nuisance) (o : Record) : ℝ :=
  treatment o*Y o/clipProp f (X o)-(1-treatment o)*Y o/(1-clipProp f (X o))
